// Integration / types feeding autocomplete
import { completionCases } from "../../harness";

completionCases("Integration: types + autocomplete", [
    { name: "a number variable does not offer array methods", source: "const n = 42;\nn.__CURSOR__\n", expectAbsent: ["push", "join", "toUpperCase"] },
    { name: "a string variable offers toUpperCase", source: "const s = \"hi\";\ns.__CURSOR__\n", expectPresent: ["toUpperCase"] },
    { name: "a string variable offers toLowerCase", source: "const s = \"HI\";\ns.__CURSOR__\n", expectPresent: ["toLowerCase"] },
    { name: "a string variable offers trim", source: "const s = \" hi \";\ns.__CURSOR__\n", expectPresent: ["trim"] },
    { name: "a boolean variable does not offer array members", source: "const b = true;\nb.__CURSOR__\n", expectAbsent: ["push", "join", "toUpperCase"] },
    { name: "an array variable offers join", source: "const a = [1, 2];\na.__CURSOR__\n", expectPresent: ["join"] },
    { name: "an array variable offers push", source: "const a = [1, 2];\na.__CURSOR__\n", expectPresent: ["push"] },
    { name: "an array variable offers filter", source: "const a = [1, 2];\na.__CURSOR__\n", expectPresent: ["filter"] },
    { name: "an array variable offers map", source: "const a = [1, 2];\na.__CURSOR__\n", expectPresent: ["map"] },
    { name: "an object literal member access offers its properties", source: "const o = { city: \"oslo\" };\no.__CURSOR__\n", expectPresent: ["city"] },
    { name: "a typed string variable offers string members", source: "const s: string = \"hi\";\ns.__CURSOR__\n", expectPresent: ["toUpperCase"] },
    { name: "a typed number variable does not offer array methods", source: "const n: number = 42;\nn.__CURSOR__\n", expectAbsent: ["push", "join", "toUpperCase"] },
    { name: "a typed array variable offers array members", source: "const xs: number[] = [1];\nxs.__CURSOR__\n", expectPresent: ["join"] },
    { name: "a string array variable offers string members on its elements", source: "const names: string[] = [\"a\"];\nnames[0].__CURSOR__\n", expectPresent: ["toLowerCase"] },
    { name: "a function parameter typed string offers string members", source: "function f(name: string): void {\n  name.__CURSOR__\n}\n", expectPresent: ["toUpperCase"] },
    { name: "a number-typed parameter does not offer array methods", source: "function f(n: number): void {\n  n.__CURSOR__\n}\n", expectAbsent: ["push", "join", "toUpperCase"] },
    { name: "a const from a string method offers string members", source: "const up = \"hi\".toUpperCase();\nup.__CURSOR__\n", expectPresent: ["toLowerCase"] },
    { name: "a numeric const does not offer array methods", source: "const half = 84 / 2;\nhalf.__CURSOR__\n", expectAbsent: ["push", "join", "toUpperCase"] },
    { name: "an if-branch narrowed const offers its narrow type members", source: "const s = \"hi\";\nif (s.length > 0) {\n  s.__CURSOR__\n}\n", expectPresent: ["toUpperCase"] },
    { name: "a return value typed array offers array members", source: "function xs(): number[] {\n  return [1];\n}\nconst value = xs();\nvalue.__CURSOR__\n", expectPresent: ["join"] },
    { name: "a const from an async function does not offer array methods", source: "async function f(): Promise<number> {\n  return 1;\n}\nconst value = 1;\nvalue.__CURSOR__\n", expectAbsent: ["push", "join", "toUpperCase"] },
    { name: "a generic instantiated with string offers string members", source: "class Box<T> {\n  value: T = 0 as T;\n}\nconst b = new Box<string>();\nb.value.__CURSOR__\n", expectPresent: ["toUpperCase"] },
    { name: "a number generic does not offer array methods", source: "class Box<T> {\n  value: T = 0 as T;\n}\nconst b = new Box<number>();\nb.value.__CURSOR__\n", expectAbsent: ["push", "join", "toUpperCase"] },
    { name: "a member of a returned object literal offers its properties", source: "class Factory {\n  make(): { label: string } {\n    return { label: \"x\" };\n  }\n}\nconst f = new Factory();\nf.make().__CURSOR__\n", expectPresent: ["label"] },
    { name: "a union member access does not offer foreign members", source: "const x: string | number = 1;\nx.__CURSOR__\n", expectAbsent: ["push", "join", "toUpperCase"] },
    { name: "a string enum member offers string members", source: "enum S { A = \"a\" }\nconst s = S.A;\ns.__CURSOR__\n", expectPresent: ["toUpperCase"] },
    { name: "an array accessed via index offers element members", source: "const xs = [\"a\", \"b\"];\nconst el = xs[0];\nel.__CURSOR__\n", expectPresent: ["toLowerCase"] },
    { name: "an array of numbers offers array methods on the array", source: "const xs = [1, 2];\nxs.__CURSOR__\n", expectPresent: ["sort"] },
    { name: "an interface-typed parameter offers its member properties", source: "interface Config { retries: number }\nfunction f(c: Config): void {\n  c.__CURSOR__\n}\n", expectPresent: ["retries"] },
    { name: "an interface-typed parameter does not offer absent members", source: "interface Config { retries: number }\nfunction f(c: Config): void {\n  c.__CURSOR__\n}\n", expectAbsent: ["timeout"] },
    { name: "a class instance from a generic array offers its members", source: "class Widget {\n  render(): void {}\n}\nconst widgets: Widget[] = [new Widget()];\nwidgets[0].__CURSOR__\n", expectPresent: ["render"] },
    { name: "a string in a template placeholder offers string members", source: "const s = \"hi\";\nconst t = `${s.__CURSOR__}`;\n", expectPresent: ["toUpperCase"] },
    { name: "a long chain of string calls stays string-typed", source: "const s = \"hello\".trim().toLowerCase();\ns.__CURSOR__\n", expectPresent: ["toUpperCase"] },
    { name: "parseInt result does not offer array methods", source: "const n = parseInt(\"42\");\nn.__CURSOR__\n", expectAbsent: ["push", "join", "toUpperCase"] },
    { name: "an object with mixed types offers its member names", source: "const mix = { s: \"x\", n: 1, b: true };\nmix.__CURSOR__\n", expectPresent: ["s", "n", "b"] },
    { name: "a member of an optional field answers well-formed", source: "interface Config { retries?: number }\nconst c: Config = {};\nc.__CURSOR__\n", expectPresent: ["retries"] },
    { name: "a return value from identity() preserves the input type", source: "function identity<T>(v: T): T { return v; }\nconst s = identity(\"hi\");\ns.__CURSOR__\n", expectPresent: ["toUpperCase"] },
    { name: "a nested generic preserves the inner member type", source: "function box<T>(v: T): { item: T } { return { item: v }; }\nconst b = box(\"hi\");\nb.item.__CURSOR__\n", expectPresent: ["toUpperCase"] },
    { name: "a generic array element keeps element type members", source: "const xs = [\"a\"];\nconst doubled = xs.map((s) => s + s);\ndoubled[0].__CURSOR__\n", expectPresent: ["toUpperCase"] },
    { name: "a spread of strings into array keeps element types", source: "const a = [\"x\"];\nconst b = [...a];\nb[0].__CURSOR__\n", expectPresent: ["toUpperCase"] },
]);
